def stamp_shapes(grid, shapes):
    """Each nonzero seed cell stamps its color's shape (list of ((dr,dc),val)); cells hit twice or more become 4."""
    h, w = len(grid), len(grid[0])
    out = [[0]*w for _ in range(h)]
    cnt = [[0]*w for _ in range(h)]
    for i, row in enumerate(grid):
        for j, v in enumerate(row):
            if v:
                for (di, dj), val in shapes[v]:
                    r, c = i+di, j+dj
                    if 0 <= r < h and 0 <= c < w:
                        cnt[r][c] += 1
                        if cnt[r][c] > 1:
                            out[r][c] = 4
                        elif out[r][c] == 0:
                            out[r][c] = val
    return out

def diagonal_beams_from(grid, marker=4, dr=1, dc=-1):
    """From every cell equal to marker, extend a diagonal ray of the marker color (default down-left) to the grid edge."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    for i in range(h):
        for j in range(w):
            if out[i][j] == marker:
                r, c = i+dr, j+dc
                while 0 <= r < h and 0 <= c < w:
                    out[r][c] = marker
                    r += dr; c += dc
    return out
